CREATE DATABASE IF NOT EXISTS eventra CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE eventra;
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(160) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('customer','admin') NOT NULL DEFAULT 'customer',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL,slug VARCHAR(80) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS events (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,description TEXT,category_id INT NOT NULL,organizer_id INT NOT NULL,starts_at DATETIME NOT NULL,venue VARCHAR(180) NOT NULL,image_url VARCHAR(500),status ENUM('draft','published','cancelled') NOT NULL DEFAULT 'draft',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id),FOREIGN KEY(organizer_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS ticket_types (id INT AUTO_INCREMENT PRIMARY KEY,event_id INT NOT NULL,name VARCHAR(80) NOT NULL,price DECIMAL(10,2) NOT NULL,available_quantity INT NOT NULL,FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS bookings (id INT AUTO_INCREMENT PRIMARY KEY,reference VARCHAR(30) NOT NULL UNIQUE,user_id INT NOT NULL,event_id INT NOT NULL,ticket_type_id INT NOT NULL,quantity INT NOT NULL,total_amount DECIMAL(10,2) NOT NULL,status ENUM('pending','confirmed','failed','cancelled') NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(event_id) REFERENCES events(id),FOREIGN KEY(ticket_type_id) REFERENCES ticket_types(id));
CREATE TABLE IF NOT EXISTS payments (id INT AUTO_INCREMENT PRIMARY KEY,booking_id INT NOT NULL,outcome ENUM('success','failed','cancelled') NOT NULL,amount DECIMAL(10,2) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(booking_id) REFERENCES bookings(id));
CREATE TABLE IF NOT EXISTS tickets (id INT AUTO_INCREMENT PRIMARY KEY,booking_id INT NOT NULL UNIQUE,ticket_code VARCHAR(40) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(booking_id) REFERENCES bookings(id));
CREATE TABLE IF NOT EXISTS event_seats (id INT AUTO_INCREMENT PRIMARY KEY,event_id INT NOT NULL,seat_label VARCHAR(30) NOT NULL,seat_row VARCHAR(10) NOT NULL,seat_number INT NOT NULL,status ENUM('available','held','sold') NOT NULL DEFAULT 'available',UNIQUE KEY event_seat_label (event_id,seat_label),FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS booking_seats (booking_id INT NOT NULL,seat_id INT NOT NULL,PRIMARY KEY(booking_id,seat_id),FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE,FOREIGN KEY(seat_id) REFERENCES event_seats(id));
